import{_ as l,a0 as a,w as r,s as d,ao as p,I as s,x as i,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"如何輕鬆安裝 Debian Linux 系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何輕鬆安裝 Debian Linux 系統 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何輕鬆安裝 Debian Linux 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何輕鬆安裝 Debian Linux 系統 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210827 How to Easily Install Debian Linux","title":"如何輕鬆安裝 Debian Linux 系統","tag":"202109","desc":""},"relativePath":"202109/20210827 How to Easily Install Debian Linux.md","filePath":"[post].md"}'),b={name:"202109/20210827 How to Easily Install Debian Linux.md"};function u(m,t,f,D,w,g){const n=a("Link");return r(),d("div",null,[t[51]||(t[51]=p('<h1 id="如何輕鬆安裝-debian-linux-系統" tabindex="-1">如何輕鬆安裝 Debian Linux 系統 <a class="header-anchor" href="#如何輕鬆安裝-debian-linux-系統" aria-label="Permalink to “如何輕鬆安裝 Debian Linux 系統”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202109/16/123647x9uz7zjjqrq0qwkk.jpg" alt=""></p><p>安裝 Debian 的輕鬆程度依賴於選擇什麼鏡像。</p><p>如果你使用 Debain 官網的默認 ISO 鏡像，安裝 Debian 就比較費勁。你會卡在這種界面，讓你從外部可移動介質上安裝網絡驅動。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Debian-firmware.png?resize=800%2C600&amp;ssl=1" alt="對於新用户來説，從默認的 ISO 中安裝 Debian 是有問題的"></p><p>當然你可以花時間去排除這個故障，但這讓事情變得沒有必要的複雜。</p><p>不用擔心，讓我來展示如何輕鬆地簡單安裝 Debian。</p><h3 id="輕鬆安裝-debian-桌面系統的方法" tabindex="-1">輕鬆安裝 Debian 桌面系統的方法 <a class="header-anchor" href="#輕鬆安裝-debian-桌面系統的方法" aria-label="Permalink to “輕鬆安裝 Debian 桌面系統的方法”">​</a></h3><p>在你查看這些步驟之前，請確認以下準備工作：</p><ul><li>一個至少 4GB 大小的 USB 盤。</li><li>一個連接了互聯網的系統（可以是要安裝 Debian 的同一個機器）。</li><li>一個要安裝的 Debian 的機器。它將會清理掉系統上所有數據，因此請複製重要數據到其他外部磁盤</li></ul>',10)),s("p",null,[t[1]||(t[1]=i("你需要為 Debian 準備什麼樣配置的機器？這取決於你想用什麼類型的 ",-1)),e(n,{href:"https://itsfoss.com/what-is-desktop-environment/"},{default:o(()=>[...t[0]||(t[0]=[i("桌面環境",-1)])]),_:1}),t[2]||(t[2]=i("。例如，GNOME 桌面系統可以在 4GB 內存上運行，但在 8GB 內存上更流暢一些。如果你只有 4GB 或更少的內存，還是建議嘗試 KDE、Cinnamon 或 Xfce 桌面系統。",-1))]),s("p",null,[t[4]||(t[4]=i("Debian 支持 ",-1)),e(n,{href:"https://itsfoss.com/32-bit-64-bit-ubuntu/"},{default:o(()=>[...t[3]||(t[3]=[i("32 位和 64 位的指令架構",-1)])]),_:1}),t[5]||(t[5]=i("。你需要根據你的 CPU 指令架構選擇對應的 Debian ISO 鏡像。",-1))]),t[52]||(t[52]=s("p",null,"你的系統應該至少要有 25GB 可用的硬盤空間。越多越好。",-1)),t[53]||(t[53]=s("blockquote",null,[s("p",null,[s("strong",null,"警告！")]),s("p",null,"這個方法會移除磁盤上所有其他操作系統及其數據。"),s("p",null,"你可以保存你後面還需要用的個人信息、文檔、照片等到外部 USB 盤或雲存儲中。")],-1)),t[54]||(t[54]=s("p",null,"在這個教程中，我將展示安裝帶有 GNOME 桌面環境的 Debian 11 Bullseye 的步驟。即使你選擇其他的桌面環境，步驟也應該是一樣的。",-1)),s("p",null,[t[8]||(t[8]=i("這個教程是在 GPT 分區的 UEFI 系統上測試的。如果你的系統是 ",-1)),e(n,{href:"https://itsfoss.com/check-mbr-or-gpt/"},{default:o(()=>[...t[6]||(t[6]=[i("MBR 而不是 GPT",-1)])]),_:1}),t[9]||(t[9]=i("，或是 ",-1)),e(n,{href:"https://itsfoss.com/check-uefi-or-bios/"},{default:o(()=>[...t[7]||(t[7]=[i("傳統的 BIOS 而不是 UEFI",-1)])]),_:1}),t[10]||(t[10]=i("，那麼創建",-1)),t[11]||(t[11]=s("ruby",null,[i("臨場"),s("rt",null,"Live")],-1)),t[12]||(t[12]=i(" USB 盤的步驟有一點不同。",-1))]),t[55]||(t[55]=p('<h4 id="步驟-1-獲取正確的-debian-iso-鏡像" tabindex="-1">步驟 1：獲取正確的 Debian ISO 鏡像 <a class="header-anchor" href="#步驟-1-獲取正確的-debian-iso-鏡像" aria-label="Permalink to “步驟 1：獲取正確的 Debian ISO 鏡像”">​</a></h4><p>在安裝 Debian 過程中，選擇正確的 ISO 鏡像就已經成功一半了。令人驚訝的是，對於一個新的 Debian 用户來説，要瀏覽 Debian 的網站並找到最輕鬆好用的 ISO 真的很困難。</p><p>如果你點擊 Debian 官網的下載按鈕，它會下載一個最小化的網絡安裝文件，這對普通用户來説是非常複雜的。請 <strong>不要</strong> 使用這個。</p><p>反而，你應該用<ruby>臨場<rt>Live</rt></ruby> ISO。但這裏要注意，有一些單獨的含有非自由軟件（以包括網絡硬件的驅動程序）的版本。</p><p>你應該下載這個非自由版的臨場 ISO 鏡像。不過另一個問題是，你不會在網站的顯著位置注意到它，而且有各種架構的 BT 種子或直接下載的 URL。</p><p>讓我把這些鏈接放在這裏：</p>',6)),s("ul",null,[s("li",null,[e(n,{href:"https://cdimage.debian.org/images/unofficial/non-free/images-including-firmware/11.0.0-live+nonfree/"},{default:o(()=>[...t[13]||(t[13]=[i("32 位和 64 位的主倉地址",-1)])]),_:1})]),s("li",null,[e(n,{href:"https://cdimage.debian.org/images/unofficial/non-free/images-including-firmware/11.0.0-live+nonfree/amd64/iso-hybrid/"},{default:o(()=>[...t[14]||(t[14]=[i("Debian 11 官方下載",-1)])]),_:1})]),s("li",null,[e(n,{href:"https://cdimage.debian.org/images/unofficial/non-free/images-including-firmware/11.0.0-live+nonfree/amd64/bt-hybrid/"},{default:o(()=>[...t[15]||(t[15]=[i("Debian 11 種子地址",-1)])]),_:1})])]),t[56]||(t[56]=s("p",null,"你會看到幾個文件，文件名中提到了桌面環境。選擇一種你要的桌面環境。直接下載的話，直接點擊 .iso 結尾的鏈接即可。",-1)),t[57]||(t[57]=s("p",null,[s("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/downloading-Debian-live-non-free-iso.png?resize=800%2C490&ssl=1",alt:"下載非自由版的臨場 Debian ISO"})],-1)),t[58]||(t[58]=s("p",null,"一旦你有了對應的 ISO 下載包，剩下就是和其他 Linux 發行版一樣的標準安裝流程了。",-1)),t[59]||(t[59]=s("h4",{id:"步驟-2-創建一個-debian-的臨場-usb-盤",tabindex:"-1"},[i("步驟 2: 創建一個 Debian 的臨場 USB 盤 "),s("a",{class:"header-anchor",href:"#步驟-2-創建一個-debian-的臨場-usb-盤","aria-label":"Permalink to “步驟 2: 創建一個 Debian 的臨場 USB 盤”"},"​")],-1)),t[60]||(t[60]=s("p",null,"將 USB 盤插入你的系統。在用之前最好格式化一下，反正它最終也會被格式化的。",-1)),t[61]||(t[61]=s("p",null,"你可以根據你的選擇使用任何臨場 USB 創建工具。如果你使用 Windows，可以使用 Rufus。我們在這裏使用 Etcher，因為這個工具在 Windows 和 Linux 都可以用。",-1)),t[62]||(t[62]=s("p",null,"從它的官網下載 Etcher。",-1)),s("ul",null,[s("li",null,[e(n,{href:"https://www.balena.io/etcher/"},{default:o(()=>[...t[16]||(t[16]=[i("下載 Etcher",-1)])]),_:1})])]),s("p",null,[t[18]||(t[18]=i("我專門寫過一篇 ",-1)),e(n,{href:"https://itsfoss.com/install-etcher-linux/"},{default:o(()=>[...t[17]||(t[17]=[i("在 Linux 下使用 Etcher 的教程",-1)])]),_:1}),t[19]||(t[19]=i("，因此這裏我就不深入介紹了。只要運行下載的可執行程序，瀏覽找到 Debian 的 ISO 鏡像，確認選擇正確的 USB 盤，然後點擊 “Flash” 按鈕即可。",-1))]),t[63]||(t[63]=s("p",null,[s("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/creating-live-debian-usb-with-etcher-800x518.png?resize=800%2C518&ssl=1",alt:"用 Etcher 創建 Debian 的臨場 USB 盤"})],-1)),t[64]||(t[64]=s("p",null,"不一會就創建好臨場 USB 盤了。創建好之後，就可以開機引導了。",-1)),t[65]||(t[65]=s("h4",{id:"步驟-3-從臨場-usb-盤引導啓動",tabindex:"-1"},[i("步驟 3：從臨場 USB 盤引導啓動 "),s("a",{class:"header-anchor",href:"#步驟-3-從臨場-usb-盤引導啓動","aria-label":"Permalink to “步驟 3：從臨場 USB 盤引導啓動”"},"​")],-1)),s("p",null,[t[21]||(t[21]=i("重啓你要安裝 Debian 的機器。當顯示製造商標識的時候，按下 ",-1)),t[22]||(t[22]=s("code",null,"F2",-1)),t[23]||(t[23]=i("、",-1)),t[24]||(t[24]=s("code",null,"F10",-1)),t[25]||(t[25]=i(" 或 ",-1)),t[26]||(t[26]=s("code",null,"F12",-1)),t[27]||(t[27]=i(" 等鍵進入開機引導設置界面。你也可以從 Windows ",-1)),e(n,{href:"https://itsfoss.com/access-uefi-settings-windows-10/"},{default:o(()=>[...t[20]||(t[20]=[i("進入到 UEFI 固件設置界面",-1)])]),_:1}),t[28]||(t[28]=i("。",-1))]),s("p",null,[t[30]||(t[30]=i("有些機器如果啓用了",-1)),t[31]||(t[31]=s("ruby",null,[i("安全啓動"),s("rt",null,"secure boot")],-1)),t[32]||(t[32]=i("功能，就不允許從臨場 USB 盤引導。如果是這種情況，請 ",-1)),e(n,{href:"https://itsfoss.com/disable-secure-boot-windows/"},{default:o(()=>[...t[29]||(t[29]=[i("從 BIOS 設置裏禁用安全啓動",-1)])]),_:1})]),t[66]||(t[66]=p('<p>不同的的製造商在界面上會有一些差異。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8.jpg?resize=700%2C525&amp;ssl=1" alt=""></p><p>你在 BIOS 裏做了修改之後，按下 <code>F10</code> 保存並退出。你的系統將會重新啓動。</p><p>再一次，當看到製造商的標識後按下 <code>F2</code>、<code>F10</code> 或 <code>F12</code> 查看引導配置。你應該可以看到從 USB 引導的選項，然後選中它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/04/boot-from-windows-disk-ventoy.jpg?resize=800%2C611&amp;ssl=1" alt=""></p><p>一會兒就會看到如下圖的顯示界面，選擇第一個選項。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/debian-live-boot-screen.png?resize=617%2C432&amp;ssl=1" alt="Debian 啓動界面"></p><h4 id="步驟-4-開始安裝-debian" tabindex="-1">步驟 4: 開始安裝 Debian <a class="header-anchor" href="#步驟-4-開始安裝-debian" aria-label="Permalink to “步驟 4: 開始安裝 Debian”">​</a></h4><p>當你進入臨場 Debian 會話，如果你使用 GNONE 桌面，它呈現一個歡迎界面，可以在此選擇你的鍵盤和語言。當你看到這些界面時，只需要點擊下一步。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/debian-live-welcome-screen.png?resize=800%2C450&amp;ssl=1" alt="Debian 臨場歡迎界面"></p><p>歡迎界面之後，按下 <code>Windows</code> / <code>Super</code> 鍵進入活動區。你應該可以看到 Debian 的安裝按鈕。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/start-Debian-installation-800x473.webp" alt="開始安裝 Debian"></p>',12)),s("p",null,[t[34]||(t[34]=i("它會打開一個友好的 ",-1)),e(n,{href:"https://calamares.io/"},{default:o(()=>[...t[33]||(t[33]=[i("Calamares 圖形安裝器",-1)])]),_:1}),t[35]||(t[35]=i("。從這裏開始事情就比較簡單了，",-1))]),t[67]||(t[67]=p('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-1.png?resize=800%2C441&amp;ssl=1" alt="Debian 11 Calamares 圖形安裝器"></p><p>它會讓你選擇你的地理位置和時區。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-2-800x441.webp" alt="選擇你的地理位置和時區"></p><p>下一個界面，會讓你選擇鍵盤類型。這兒請 <strong>注意</strong>。你的鍵盤會根據你所選的位置自動選擇。例如，我的位置是印度，它會自動默認選擇印度鍵盤和印地語。我需要將其改為印度英語。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-4-800x441.webp" alt="選擇鍵盤類型"></p><p>下一個界面是關於磁盤分區和要安裝 Debian 的地方。在本文中，把 Debian 作為你電腦上唯一的操作系統來安裝。</p><p>最簡單的方法是直接選擇 “<ruby>擦除磁盤<rt>Erase Disk</rt></ruby>”。除了必須的 ESP 分區和交換分區外，Debian 會把其他所有東西都放在根掛載點（<code>/</code>）上。實際上，下面顯示了你所選的安裝方式後的磁盤佈局。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-5.png?resize=800%2C441&amp;ssl=1" alt="磁盤分區"></p><p>如果你想把事情掌握在自己手中，你也可以選擇手動分區，選擇分配給 <code>/</code>、<code>/home</code>、<code>/boot</code> 或交換分區的大小。只有在你知道自己在做什麼時，才可以這樣做。</p><p>下一界面，你需要提供用户名和密碼。但它不會設置 root 的密碼，並將其保持為空。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-6.png?resize=800%2C441&amp;ssl=1" alt="設置用户名和密碼"></p><p>這也意味着你可以用新創建的用户使用 <code>sudo</code> 。在“複雜的 Debian 安裝”中，你也可以設置 root 密碼，但這樣你就必須手動將普通用户添加到 <code>sudoer</code> 列表。看看，這種安裝過程是不是對新手來説很容易？</p><p>在繼續實際安裝之前，它會呈現你所做的選擇的彙總信息。如果沒有問題，就可以點擊“<ruby>安裝<rt>Install</rt></ruby>”按鈕。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-7-800x500.webp" alt="安裝配置的彙總信息"></p><p>現在只需要等待安裝完成。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-8.png?resize=800%2C500&amp;ssl=1" alt="安裝 Debian"></p><p>幾分鐘後就會完成安裝。當安裝完成，它會提示重啓。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-9.png?resize=800%2C500&amp;ssl=1" alt="完成 Debian 安裝"></p><p>重啓系統後如果一切順利，你應該可以看到 Debian 的 GRUB 界面。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/debian-boot-screen.webp" alt="Debian 啓動畫面"></p><h3 id="疑難解答-如果系統沒有啓動到-debian" tabindex="-1">疑難解答（如果系統沒有啓動到 Debian） <a class="header-anchor" href="#疑難解答-如果系統沒有啓動到-debian" aria-label="Permalink to “疑難解答（如果系統沒有啓動到 Debian）”">​</a></h3><p>我遇到情況是，我的 Dell 系統不能識別任何要引導的操作系統。這很奇怪，我看見 Debian 經創建了一個 ESP 分區。</p><p>如果你也是同樣的情況，進去 BIOS 配置裏。檢查<ruby>啓動順序<rt>Boot Sequence</rt></ruby>，如果你看不到任何東西，就點擊“<ruby>新增引導選項<rt>Add Boot Option</rt></ruby>”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/add-new-boot-option.webp" alt="增加新的啓動選項"></p><p>它會提供一個增加 EFI 文件的選項。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/add-efi-file-for-boot-option.webp" alt="選擇 EFI 文件"></p><p>由於在安裝過程中 Debian 創建了 ESP 分區，因此一個包含必要文件的 <code>EFI</code> 目錄已經創建好了。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/select-efi-file-boot-option.webp" alt="選擇 EFI 目錄"></p><p>它會顯示一個 <code>Debian</code> 目錄及其他目錄。選擇 <code>Debian</code> 目錄。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/select-debian-folder-for-uefi.webp" alt="選擇 Debian 目錄"></p><p>在 <code>Debian</code> 目錄，你將看到 <code>grubx64.efi</code>、<code>shimx64.efi</code> 等文件。請選擇 <code>shimx64.efi</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/select-shim-boot.webp" alt="選擇 shimx64.efi"></p><p>你需要給這個文件一個合適的名字。最後的界面應該如下:</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/new-boot-option.webp" alt="增加 efi 文件的新啓動選項"></p><p>現在你應該有了這個啓動選項。因為我命名為 <code>Debian</code>，它顯示了兩個 <code>Debian</code> 引導選項（我猜其中一個是從 efi 文件來的）。按下 <code>F10</code> 保存退出 BIOS 的配置。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/new-boot-option-added.webp" alt="新增的啓動選項"></p><p>現在啓動你的系統，你可以看到帶有 Debian 啓動選項的 GRUB 界面了。你現在可以體驗 Debian 了。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/debian-boot-screen.webp" alt=""></p><h3 id="你能安裝-debian-嗎" tabindex="-1">你能安裝 Debian 嗎？ <a class="header-anchor" href="#你能安裝-debian-嗎" aria-label="Permalink to “你能安裝 Debian 嗎？”">​</a></h3><p>我寫這篇文章的目的是讓事情變得輕鬆點。並不是説你不能從默認的網絡安裝程序 ISO 來安裝，只是它需要花更多的精力。</p><p>這個教程對你安裝 Debian 有幫助嗎？你如果還是有問題，請在下面留言給我，我會盡力提供幫助。</p><hr>',42)),s("p",null,[t[37]||(t[37]=i("via: ",-1)),e(n,{href:"https://itsfoss.com/install-debian-easily/"},{default:o(()=>[...t[36]||(t[36]=[i("https://itsfoss.com/install-debian-easily/",-1)])]),_:1})]),s("p",null,[t[42]||(t[42]=i("作者：",-1)),e(n,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[38]||(t[38]=[i("Abhishek Prakash",-1)])]),_:1}),t[43]||(t[43]=i(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[39]||(t[39]=[i("lujun9972",-1)])]),_:1}),t[44]||(t[44]=i(" 譯者：",-1)),e(n,{href:"https://github.com/guevaraya"},{default:o(()=>[...t[40]||(t[40]=[i("巴龍",-1)])]),_:1}),t[45]||(t[45]=i(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[41]||(t[41]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[48]||(t[48]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[46]||(t[46]=[i("LCTT",-1)])]),_:1}),t[49]||(t[49]=i(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...t[47]||(t[47]=[i("Linux中國",-1)])]),_:1}),t[50]||(t[50]=i(" 榮譽推出",-1))])])}const T=l(b,[["render",u]]);export{I as __pageData,T as default};
